// TestimonialSlider.tsx
import React, { useState, useEffect, useRef } from 'react';
import '../Styles/TestimonialSlider.css';
import { ALL_REVIEWS } from '../data/reviews';
import { GOOGLE_RATING, GOOGLE_REVIEW_COUNT, PROFILE_LINKS } from '../data/business';

const stats = [
  { title: 'Google Rating', value: GOOGLE_RATING, desc: `From ${GOOGLE_REVIEW_COUNT} Google Reviews` },
  { title: 'BBB Rating', value: 'A+', desc: 'Accredited Since 2023' },
  { title: 'Certified Plus™', value: 'GAF', desc: 'Listed in GAF Directory' },
];

const TestimonialSlider: React.FC = () => {
  const sliderRef = useRef<HTMLDivElement>(null);
  // The second copy only exists to loop the scroll. It's added after mount so
  // the static HTML that crawlers read lists each review once.
  const [loopReady, setLoopReady] = useState(false);

  useEffect(() => {
    setLoopReady(true);
  }, []);

  // Initialize animation
  useEffect(() => {
    const slider = sliderRef.current;
    if (!slider) return;

    // Create a smooth animation using CSS transitions
    slider.style.transition = 'transform 0.6s cubic-bezier(0.22, 0.61, 0.36, 1)';

    const animate = () => {
      if (slider) {
        const scrollAmount = 1;
        slider.scrollLeft += scrollAmount;

        // Reset to beginning when reaching end
        if (slider.scrollLeft >= slider.scrollWidth / 2) {
          slider.style.transition = 'none';
          slider.scrollLeft = 0;
          // Force reflow to apply transition reset
          void slider.offsetWidth;
          slider.style.transition = 'transform 0.6s cubic-bezier(0.22, 0.61, 0.36, 1)';
        }
      }

      requestAnimationFrame(animate);
    };

    animate();

    return () => {
      // Cleanup if needed
    };
  }, []);

  return (
    <div className="testimonial-slider-container" id="reviews">
      <div className="slider-header">
        <h2>Customer Testimonials</h2>
        <p>
          Here's what homeowners have said about working with us. Read more on our{' '}
          <a href="/reviews/" className="inline-link">reviews page</a> or on{' '}
          <a href={PROFILE_LINKS.google} className="inline-link" target="_blank" rel="noopener noreferrer">Google</a>.
        </p>
      </div>

      <div
        className="testimonial-slider"
        ref={sliderRef}
      >
        {(loopReady ? [...ALL_REVIEWS, ...ALL_REVIEWS] : ALL_REVIEWS).map((review, index) => (
          <div
            key={`${review.author}-${index}`}
            className="testimonial-card"
            aria-hidden={index >= ALL_REVIEWS.length}
          >
            <div className="quote-icon">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
                <path d="M14.017 21v-7.391c0-5.704 3.731-9.57 8.983-10.609l.515 2.151c-2.432.917-3.515 3.638-3.515 5.849h4v10h-9.983zm-14.017 0v-7.391c0-5.704 3.748-9.57 9-10.609l.996 2.151c-2.433.917-3.996 3.638-3.996 5.849h3.983v10h-9.983z"/>
              </svg>
            </div>
            <p className="testimonial-content">{review.excerpt ?? review.text}</p>
            <div className="rating">
              {[...Array(5)].map((_, i) => (
                <svg key={i} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
                  <path d="M12 .587l3.668 7.568 8.332 1.151-6.064 5.828 1.48 8.279-7.416-3.967-7.417 3.967 1.481-8.279-6.064-5.828 8.332-1.151z"/>
                </svg>
              ))}
            </div>
            <div className="client-info">
              <div className="avatar avatar--initial" aria-hidden="true">
                {review.author.charAt(0).toUpperCase()}
              </div>
              <div className="client-details">
                <h3>{review.author}</h3>
                <p>{review.location ?? 'Bravo Roofing Customer'}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="stats-container">
        {stats.map((stat) => (
          <div key={stat.title} className="stat-card">
            <div className="stat-content">
              <div className="stat-value">{stat.value}</div>
              <div className="stat-title">{stat.title}</div>
              <p className="stat-desc">{stat.desc}</p>
            </div>
          </div>
        ))}
      </div>

    </div>
  );
};

export default TestimonialSlider;
