import React, { useState, useEffect, useRef } from 'react';
import { FaChevronLeft, FaChevronRight, FaSearchPlus, FaTimes } from 'react-icons/fa';
import '../Styles/projects.css';
import { bravoRoofingImageApi, type ImageRecord } from '../ppm/cfimages/imageApi';

const PortfolioSlider = () => {
  const [images, setImages] = useState<ImageRecord[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [itemsPerView, setItemsPerView] = useState(3);
  const [hoveredItem, setHoveredItem] = useState<number | null>(null);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const autoSlideRef = useRef<NodeJS.Timeout | null>(null);

  // ── Load all images from the API (CMS uploads + static built-ins) ───────────
  useEffect(() => {
    bravoRoofingImageApi.fetchFiles().then(records => {
      setImages(records);
      setCurrentIndex(0);
    });
  }, []);

  // ── Responsive items per view ───────────────────────────────────────────────
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 576) setItemsPerView(1);
      else if (window.innerWidth <= 992) setItemsPerView(2);
      else setItemsPerView(3);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ── Auto slide ──────────────────────────────────────────────────────────────
  useEffect(() => {
    if (autoSlideRef.current) clearInterval(autoSlideRef.current);
    autoSlideRef.current = setInterval(goToNext, 5000);
    return () => { if (autoSlideRef.current) clearInterval(autoSlideRef.current); };
  }, [itemsPerView, images.length]);

  const goToNext = () =>
    setCurrentIndex(prev => (prev + itemsPerView) >= images.length ? 0 : prev + itemsPerView);

  const goToPrev = () =>
    setCurrentIndex(prev =>
      prev - itemsPerView < 0
        ? Math.floor((images.length - 1) / itemsPerView) * itemsPerView
        : prev - itemsPerView
    );

  const visibleImages = images.slice(currentIndex, currentIndex + itemsPerView);
  const fillerImages = Array(itemsPerView - visibleImages.length).fill(null);

  useEffect(() => { setHoveredItem(null); }, [currentIndex]);

  // ── Lightbox ────────────────────────────────────────────────────────────────
  const openLightbox = (index: number) => {
    setLightboxIndex(index);
    setLightboxOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setLightboxOpen(false);
    document.body.style.overflow = 'auto';
  };

  const nextLightboxImage = () => setLightboxIndex(prev => (prev + 1) % images.length);
  const prevLightboxImage = () => setLightboxIndex(prev => (prev - 1 + images.length) % images.length);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (!lightboxOpen) return;
      if (e.key === 'Escape') closeLightbox();
      else if (e.key === 'ArrowRight') nextLightboxImage();
      else if (e.key === 'ArrowLeft') prevLightboxImage();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [lightboxOpen]);

  if (images.length === 0) return null;

  return (
    <div className="portfolio-slider-container" id="portfolio">
      <div className="portfolio-header">
        <h2>Our Creative Portfolio</h2>
        <p>Explore our latest projects and design solutions that showcase our expertise</p>
      </div>

      <div
        className="portfolio-slider"
        onMouseEnter={() => {
          if (autoSlideRef.current) { clearInterval(autoSlideRef.current); autoSlideRef.current = null; }
        }}
        onMouseLeave={() => {
          if (!autoSlideRef.current) autoSlideRef.current = setInterval(goToNext, 5000);
        }}
      >
        <button className="slider-btn prev" onClick={goToPrev} aria-label="Previous slide">
          <FaChevronLeft />
        </button>

        <div className="slider-items">
          {visibleImages.map((image, index) => {
            const absoluteIndex = currentIndex + index;
            return (
              <div
                key={image.id}
                className="slider-item"
                onMouseEnter={() => setHoveredItem(absoluteIndex)}
                onMouseLeave={() => setHoveredItem(null)}
                onClick={() => openLightbox(absoluteIndex)}
              >
                <img src={image.path} alt={image.name} className="portfolio-image" />
                <div className={`image-overlay ${hoveredItem === absoluteIndex ? 'active' : ''}`}>
                  <FaSearchPlus className="preview-icon" />
                  <span className="image-number">{absoluteIndex + 1}/{images.length}</span>
                </div>
              </div>
            );
          })}

          {fillerImages.map((_, index) => (
            <div key={`filler-${index}`} className="slider-item filler" aria-hidden="true" />
          ))}
        </div>

        <button className="slider-btn next" onClick={goToNext} aria-label="Next slide">
          <FaChevronRight />
        </button>
      </div>

      <div className="slider-dots">
        {Array.from({ length: Math.ceil(images.length / itemsPerView) }).map((_, index) => (
          <button
            key={index}
            className={`dot ${index === Math.floor(currentIndex / itemsPerView) ? 'active' : ''}`}
            onClick={() => setCurrentIndex(index * itemsPerView)}
            aria-label={`Go to slide ${index + 1}`}
          />
        ))}
      </div>

      {/* Lightbox */}
      {lightboxOpen && images[lightboxIndex] && (
        <div className="lightbox active">
          <div className="lightbox-content">
            <img
              src={images[lightboxIndex].path}
              alt={images[lightboxIndex].name}
              className="lightbox-image"
            />
            <div className="lightbox-caption">{images[lightboxIndex].name}</div>
            <button className="lightbox-close" onClick={closeLightbox}><FaTimes /></button>
            <button className="lightbox-nav lightbox-prev" onClick={prevLightboxImage}><FaChevronLeft /></button>
            <button className="lightbox-nav lightbox-next" onClick={nextLightboxImage}><FaChevronRight /></button>
          </div>
        </div>
      )}
    </div>
  );
};

export default PortfolioSlider;
